from __future__ import annotations
import math

def S(k: int, n: int) -> int:
    if k < 2 or n < 0: raise ValueError("require k >= 2 and n >= 0")
    return (k ** (n + 1) - 1) // (k - 1)

def trajectory(k: int, a: int, limit: int) -> list[tuple[int, float, float]]:
    if not 0 <= a < k: raise ValueError("require 0 <= a < k")
    return [(n, a ** n / S(k, n), math.log(S(k, n)) / n)
            for n in range(1, limit + 1)]

if __name__ == "__main__":
    print("n density entropy")
    for n, rho, h in trajectory(3, 2, 15):
        print(n, f"{rho:.8f}", f"{h:.8f}")
    print("entropy limit", math.log(3))

from __future__ import annotations
from fractions import Fraction
from typing import Callable, Optional

def S(k: int, n: int) -> int:
    return (k ** (n + 1) - 1) // (k - 1)

def crossing(k: int, P: Callable[[int], int], eps: Fraction,
             limit: int) -> Optional[int]:
    rho = [Fraction(P(n), S(k, n)) for n in range(limit + 1)]
    if any(rho[n + 1] > rho[n] for n in range(limit)):
        raise ValueError("density must be antitone")
    return next((n for n in range(limit) if rho[n] >= eps > rho[n + 1]), None)

if __name__ == "__main__":
    c = crossing(3, lambda n: 2 ** n, Fraction(1, 4), 20)
    print("critical index:", c)
    assert c == 2

from __future__ import annotations
import math

def length_probability(k: float, n: int) -> float:
    if k <= 1 or n < 0: raise ValueError("require k > 1 and n >= 0")
    return (1 - 1 / k) * math.exp(-n * math.log(k))

def ratios(k: float, limit: int) -> list[float]:
    p = [length_probability(k, n) for n in range(limit + 1)]
    return [p[n + 1] / p[n] for n in range(limit)]

if __name__ == "__main__":
    for k in (2.0, 3.0, 4.0):
        values = ratios(k, 8)
        print(k, values)
        assert all(abs(r - 1 / k) < 1e-12 for r in values)

